diff --git a/README.md b/README.md
index 1ea4bfd..45eec4c 100644
--- a/README.md
+++ b/README.md
@@ -1,2 +1,14 @@
 # CartStock
-Implement the public API specified in SPEC.md.
+
+In-memory inventory holds with atomic cart edits. The logical clock advances only
+when `advance` is called.
+
+```js
+import { createStockroom } from './src/stockroom.js';
+
+const stockroom = createStockroom({ stock: { BOOK: 5, PEN: 12 } });
+const hold = stockroom.reserve({
+  id: 'cart-1', owner: 'customer-7', items: { BOOK: 2, PEN: 3 }, ttl: 300,
+});
+console.log(hold.expiresAt, stockroom.availability());
+```
diff --git a/src/stockroom.js b/src/stockroom.js
index b0bb026..f09e85c 100644
--- a/src/stockroom.js
+++ b/src/stockroom.js
@@ -1,2 +1,200 @@
-export function createStockroom() { throw new Error('Not implemented'); }
-export function restoreStockroom() { throw new Error('Not implemented'); }
+const SKU = /^[A-Za-z][A-Za-z0-9_-]{0,31}$/;
+
+function fail(code, message = code) {
+  const error = new Error(message);
+  error.code = code;
+  throw error;
+}
+
+function record(value) {
+  return value !== null && typeof value === 'object' && !Array.isArray(value);
+}
+
+function safeInteger(value, minimum) {
+  return Number.isSafeInteger(value) && value >= minimum;
+}
+
+function cloneMap(map) {
+  return Object.assign({}, map);
+}
+
+function sameItems(left, right) {
+  const a = Object.keys(left);
+  const b = Object.keys(right);
+  return a.length === b.length && a.every((key) => Object.hasOwn(right, key) && left[key] === right[key]);
+}
+
+function makeStockroom(onHand, now, reservations = new Map()) {
+  function view(reservation) {
+    return {
+      id: reservation.id,
+      owner: reservation.owner,
+      items: cloneMap(reservation.items),
+      expiresAt: reservation.expiresAt,
+      state: reservation.state,
+      version: reservation.version,
+    };
+  }
+
+  function validateIdentity(id, owner) {
+    if (typeof id !== 'string' || id.length < 1 || id.length > 64 ||
+        typeof owner !== 'string' || owner.length < 1 || owner.length > 64) fail('INVALID');
+  }
+
+  function validateItems(items) {
+    if (!record(items) || Object.keys(items).length === 0) fail('INVALID');
+    const copied = {};
+    for (const sku of Object.keys(items)) {
+      if (!SKU.test(sku)) fail('INVALID');
+      if (!Object.hasOwn(onHand, sku)) fail('UNKNOWN_SKU');
+      if (!safeInteger(items[sku], 1)) fail('INVALID');
+      Object.defineProperty(copied, sku, { value: items[sku], enumerable: true, writable: true, configurable: true });
+    }
+    return copied;
+  }
+
+  function deadline(ttl) {
+    if (!safeInteger(ttl, 1) || !Number.isSafeInteger(now + ttl)) fail('INVALID');
+    return now + ttl;
+  }
+
+  function availableWithCredit(items = null) {
+    const result = cloneMap(onHand);
+    for (const reservation of reservations.values()) {
+      if (reservation.state !== 'held') continue;
+      for (const sku of Object.keys(reservation.items)) result[sku] -= reservation.items[sku];
+    }
+    if (items) for (const sku of Object.keys(items)) result[sku] += items[sku];
+    return result;
+  }
+
+  function requireReservation(id) {
+    if (typeof id !== 'string' || id.length < 1 || id.length > 64) fail('INVALID');
+    const reservation = reservations.get(id);
+    if (!reservation) fail('UNKNOWN_RESERVATION');
+    return reservation;
+  }
+
+  function authorize(reservation, owner, version) {
+    if (typeof owner !== 'string' || owner.length < 1 || owner.length > 64) fail('INVALID');
+    if (reservation.owner !== owner) fail('FORBIDDEN');
+    if (reservation.state !== 'held') fail('STATE');
+    if (!safeInteger(version, 1)) fail('INVALID');
+    if (reservation.version !== version) fail('VERSION_CONFLICT');
+  }
+
+  return {
+    reserve({ id, owner, items, ttl } = {}) {
+      validateIdentity(id, owner);
+      const requestedItems = validateItems(items);
+      if (!safeInteger(ttl, 1)) fail('INVALID');
+      const existing = reservations.get(id);
+      if (existing) {
+        if (existing.initialRequest.owner !== owner || existing.initialRequest.ttl !== ttl ||
+            !sameItems(existing.initialRequest.items, requestedItems)) fail('ID_CONFLICT');
+        return view(existing);
+      }
+      const expiresAt = deadline(ttl);
+      const available = availableWithCredit();
+      if (Object.keys(requestedItems).some((sku) => requestedItems[sku] > available[sku])) fail('INSUFFICIENT');
+      const reservation = {
+        id, owner, items: requestedItems, expiresAt, state: 'held', version: 1,
+        initialRequest: { owner, items: cloneMap(requestedItems), ttl },
+      };
+      reservations.set(id, reservation);
+      return view(reservation);
+    },
+
+    amend({ id, owner, version, items, ttl } = {}) {
+      const reservation = requireReservation(id);
+      authorize(reservation, owner, version);
+      const replacement = validateItems(items);
+      const expiresAt = ttl === undefined ? reservation.expiresAt : deadline(ttl);
+      const available = availableWithCredit(reservation.items);
+      if (Object.keys(replacement).some((sku) => replacement[sku] > available[sku])) fail('INSUFFICIENT');
+      reservation.items = replacement;
+      reservation.expiresAt = expiresAt;
+      reservation.version += 1;
+      return view(reservation);
+    },
+
+    confirm({ id, owner, version } = {}) {
+      const reservation = requireReservation(id);
+      authorize(reservation, owner, version);
+      for (const sku of Object.keys(reservation.items)) onHand[sku] -= reservation.items[sku];
+      reservation.state = 'confirmed';
+      reservation.version += 1;
+      return view(reservation);
+    },
+
+    cancel({ id, owner, version } = {}) {
+      const reservation = requireReservation(id);
+      authorize(reservation, owner, version);
+      reservation.state = 'cancelled';
+      reservation.version += 1;
+      return view(reservation);
+    },
+
+    get(id) { return view(requireReservation(id)); },
+
+    availability() { return availableWithCredit(); },
+
+    advance(time) {
+      if (!safeInteger(time, 0) || time < now) fail('INVALID_TIME');
+      now = time;
+      const expired = [...reservations.values()]
+        .filter((reservation) => reservation.state === 'held' && reservation.expiresAt <= time)
+        .sort((a, b) => a.expiresAt - b.expiresAt || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
+      for (const reservation of expired) {
+        reservation.state = 'expired';
+        reservation.version += 1;
+      }
+      return { now, expired: expired.map(({ id }) => id) };
+    },
+
+    snapshot() {
+      const ordered = [...reservations.values()].sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
+      return {
+        schemaVersion: 1,
+        now,
+        onHand: cloneMap(onHand),
+        reservations: ordered.map((reservation) => ({
+          ...view(reservation),
+          initialRequest: {
+            owner: reservation.initialRequest.owner,
+            items: cloneMap(reservation.initialRequest.items),
+            ttl: reservation.initialRequest.ttl,
+          },
+        })),
+      };
+    },
+  };
+}
+
+export function createStockroom({ stock, now = 0 } = {}) {
+  if (!record(stock) || Object.keys(stock).length === 0 || !safeInteger(now, 0)) fail('INVALID');
+  const onHand = {};
+  for (const sku of Object.keys(stock)) {
+    if (!SKU.test(sku) || !safeInteger(stock[sku], 0)) fail('INVALID');
+    Object.defineProperty(onHand, sku, { value: stock[sku], enumerable: true, writable: true, configurable: true });
+  }
+  return makeStockroom(onHand, now);
+}
+
+export function restoreStockroom(snapshot) {
+  // Restore only snapshots produced by this module, as required by the contract.
+  const reservations = new Map(snapshot.reservations.map((entry) => [entry.id, {
+    id: entry.id,
+    owner: entry.owner,
+    items: cloneMap(entry.items),
+    expiresAt: entry.expiresAt,
+    state: entry.state,
+    version: entry.version,
+    initialRequest: {
+      owner: entry.initialRequest.owner,
+      items: cloneMap(entry.initialRequest.items),
+      ttl: entry.initialRequest.ttl,
+    },
+  }]));
+  return makeStockroom(cloneMap(snapshot.onHand), snapshot.now, reservations);
+}
diff --git a/tests/stockroom.contract.test.js b/tests/stockroom.contract.test.js
new file mode 100644
index 0000000..483c74a
--- /dev/null
+++ b/tests/stockroom.contract.test.js
@@ -0,0 +1,214 @@
+import { describe, expect, test } from 'vitest';
+import { createStockroom, restoreStockroom } from '../src/stockroom.js';
+
+function expectCode(action, code) {
+  try {
+    action();
+    throw new Error(`Expected error code ${code}`);
+  } catch (error) {
+    expect(error).toBeInstanceOf(Error);
+    expect(error.code).toBe(code);
+  }
+}
+
+describe('CartStock public contract', () => {
+  test('[R-2] validates stock, item maps, identifiers, owners, time, TTL, and versions', () => {
+    for (const stock of [{}, { '1bad': 1 }, { A: -1 }, { A: Number.MAX_SAFE_INTEGER + 1 }, null]) {
+      expectCode(() => createStockroom({ stock }), 'INVALID');
+    }
+    expect(createStockroom({ stock: { constructor: 2 } }).availability()).toEqual({ constructor: 2 });
+    expectCode(() => createStockroom({ stock: { A: 1 }, now: -1 }), 'INVALID');
+    const room = createStockroom({ stock: { A: 2 } });
+    for (const items of [null, {}, { A: 0 }, { A: 1.5 }, { Missing: 1 }]) {
+      expectCode(() => room.reserve({ id: 'x', owner: 'u', items, ttl: 1 }), items?.Missing ? 'UNKNOWN_SKU' : 'INVALID');
+    }
+    expectCode(() => room.reserve({ id: '', owner: 'u', items: { A: 1 }, ttl: 1 }), 'INVALID');
+    expectCode(() => room.reserve({ id: 'x', owner: '', items: { A: 1 }, ttl: 1 }), 'INVALID');
+    expectCode(() => room.reserve({ id: 'x', owner: 'u', items: { A: 1 }, ttl: 0 }), 'INVALID');
+    expectCode(() => createStockroom({ stock: { A: 1 }, now: Number.MAX_SAFE_INTEGER }).reserve({ id: 'x', owner: 'u', items: { A: 1 }, ttl: 1 }), 'INVALID');
+    room.reserve({ id: 'v', owner: 'u', items: { A: 1 }, ttl: 2 });
+    for (const version of [0, 1.1, Number.MAX_SAFE_INTEGER + 1]) {
+      expectCode(() => room.cancel({ id: 'v', owner: 'u', version }), 'INVALID');
+    }
+  });
+
+  test('[R-3] reserves atomically at version one and leaves state unchanged when capacity is insufficient', () => {
+    const room = createStockroom({ stock: { A: 2, B: 1 } });
+    const held = room.reserve({ id: 'first', owner: 'u', items: { A: 2, B: 1 }, ttl: 5 });
+    expect(held).toMatchObject({ expiresAt: 5, state: 'held', version: 1 });
+    const before = room.snapshot();
+    expectCode(() => room.reserve({ id: 'second', owner: 'v', items: { A: 1, B: 1 }, ttl: 5 }), 'INSUFFICIENT');
+    expect(room.snapshot()).toEqual(before);
+  });
+
+  test('[R-4] returns exact detached views and reports missing reservations', () => {
+    const room = createStockroom({ stock: { A: 3 } });
+    const submitted = { A: 1 };
+    const created = room.reserve({ id: 'r', owner: 'u', items: submitted, ttl: 3 });
+    submitted.A = 3;
+    expect(Object.keys(created)).toEqual(['id', 'owner', 'items', 'expiresAt', 'state', 'version']);
+    created.items.A = 3;
+    expect(room.get('r').items).toEqual({ A: 1 });
+    expectCode(() => room.get('missing'), 'UNKNOWN_RESERVATION');
+    const amended = room.amend({ id: 'r', owner: 'u', version: 1, items: { A: 2 } });
+    expect(Object.keys(amended)).toEqual(['id', 'owner', 'items', 'expiresAt', 'state', 'version']);
+    amended.items.A = 1;
+    expect(room.get('r').items).toEqual({ A: 2 });
+  });
+
+  test('[R-5] reserve replays match the initial request independent of item key order', () => {
+    const room = createStockroom({ stock: { A: 5, B: 5 } });
+    room.reserve({ id: 'r', owner: 'u', items: { A: 1, B: 2 }, ttl: 8 });
+    const amended = room.amend({ id: 'r', owner: 'u', version: 1, items: { A: 3 } });
+    const before = room.snapshot();
+    expect(room.reserve({ id: 'r', owner: 'u', items: { B: 2, A: 1 }, ttl: 8 })).toEqual(amended);
+    expect(room.snapshot()).toEqual(before);
+    for (const changed of [
+      { owner: 'other', items: { A: 1, B: 2 }, ttl: 8 },
+      { owner: 'u', items: { A: 2, B: 2 }, ttl: 8 },
+      { owner: 'u', items: { A: 1, B: 2 }, ttl: 9 },
+    ]) expectCode(() => room.reserve({ id: 'r', ...changed }), 'ID_CONFLICT');
+  });
+
+  test('[R-6] replay validates fields but keeps the original deadline across terminal state and restore', () => {
+    const room = createStockroom({ stock: { A: 4 } });
+    room.reserve({ id: 'r', owner: 'u', items: { A: 1 }, ttl: 2 });
+    room.advance(1);
+    room.confirm({ id: 'r', owner: 'u', version: 1 });
+    const restored = restoreStockroom(JSON.parse(JSON.stringify(room.snapshot())));
+    expect(restored.reserve({ id: 'r', owner: 'u', items: { A: 1 }, ttl: 2 })).toEqual({
+      id: 'r', owner: 'u', items: { A: 1 }, expiresAt: 2, state: 'confirmed', version: 2,
+    });
+    expectCode(() => restored.reserve({ id: 'r', owner: 'u', items: { A: 1 }, ttl: 3 }), 'ID_CONFLICT');
+
+    const expiredRoom = createStockroom({ stock: { A: 1 } });
+    expiredRoom.reserve({ id: 'old', owner: 'u', items: { A: 1 }, ttl: 1 });
+    expiredRoom.advance(1);
+    expiredRoom.reserve({ id: 'replacement', owner: 'v', items: { A: 1 }, ttl: 5 });
+    expect(expiredRoom.reserve({ id: 'old', owner: 'u', items: { A: 1 }, ttl: 1 }))
+      .toMatchObject({ state: 'expired', expiresAt: 1, version: 2 });
+  });
+
+  test('[R-7] checks owner, then terminal state, then version', () => {
+    const room = createStockroom({ stock: { A: 3 } });
+    room.reserve({ id: 'held', owner: 'u', items: { A: 1 }, ttl: 5 });
+    expectCode(() => room.cancel({ id: 'held', owner: 'wrong', version: 99 }), 'FORBIDDEN');
+    expectCode(() => room.cancel({ id: 'held', owner: 'u', version: 99 }), 'VERSION_CONFLICT');
+    room.cancel({ id: 'held', owner: 'u', version: 1 });
+    expectCode(() => room.confirm({ id: 'held', owner: 'wrong', version: 1 }), 'FORBIDDEN');
+    expectCode(() => room.confirm({ id: 'held', owner: 'u', version: 1 }), 'STATE');
+  });
+
+  test('[R-8] successful edits increment once and failed commands preserve the full snapshot', () => {
+    const room = createStockroom({ stock: { A: 4 } });
+    room.reserve({ id: 'r', owner: 'u', items: { A: 1 }, ttl: 5 });
+    expect(room.amend({ id: 'r', owner: 'u', version: 1, items: { A: 1 } }).version).toBe(2);
+    const before = room.snapshot();
+    expectCode(() => room.confirm({ id: 'r', owner: 'u', version: 1 }), 'VERSION_CONFLICT');
+    expect(room.snapshot()).toEqual(before);
+    expect(room.cancel({ id: 'r', owner: 'u', version: 2 }).version).toBe(3);
+  });
+
+  test('[R-9] amend credits the old hold, replaces all items atomically, and applies expiry rules', () => {
+    const room = createStockroom({ stock: { A: 5, B: 2 } });
+    room.reserve({ id: 'r', owner: 'u', items: { A: 2 }, ttl: 10 });
+    const failedState = room.snapshot();
+    expectCode(() => room.amend({ id: 'r', owner: 'u', version: 1, items: { A: 4, B: 3 }, ttl: 20 }), 'INSUFFICIENT');
+    expect(room.snapshot()).toEqual(failedState);
+    const same = room.amend({ id: 'r', owner: 'u', version: 1, items: { A: 2 } });
+    expect(same).toMatchObject({ version: 2, expiresAt: 10, items: { A: 2 } });
+    expect(room.amend({ id: 'r', owner: 'u', version: 2, items: { B: 2 }, ttl: 4 })).toMatchObject({ version: 3, expiresAt: 4, items: { B: 2 } });
+    expect(room.availability()).toEqual({ A: 5, B: 0 });
+  });
+
+  test('[R-10] confirm preserves availability and cancel releases holds without changing on-hand stock', () => {
+    const room = createStockroom({ stock: { A: 5, B: 3 } });
+    room.reserve({ id: 'confirm', owner: 'u', items: { A: 2 }, ttl: 5 });
+    const beforeConfirm = room.availability();
+    room.confirm({ id: 'confirm', owner: 'u', version: 1 });
+    expect(room.availability()).toEqual(beforeConfirm);
+    const onHandAfterConfirm = room.snapshot().onHand;
+    room.reserve({ id: 'cancel', owner: 'v', items: { B: 2 }, ttl: 5 });
+    room.cancel({ id: 'cancel', owner: 'v', version: 1 });
+    expect(room.availability()).toEqual({ A: 3, B: 3 });
+    expect(room.snapshot().onHand).toEqual(onHandAfterConfirm);
+  });
+
+  test('[R-11] terminal reservations retain items and expiry and reject repeat commands', () => {
+    const room = createStockroom({ stock: { A: 2 } });
+    const held = room.reserve({ id: 'r', owner: 'u', items: { A: 1 }, ttl: 3 });
+    const terminal = room.confirm({ id: 'r', owner: 'u', version: 1 });
+    expect(terminal.items).toEqual(held.items);
+    expect(terminal.expiresAt).toBe(held.expiresAt);
+    expectCode(() => room.confirm({ id: 'r', owner: 'u', version: 2 }), 'STATE');
+    expectCode(() => room.cancel({ id: 'r', owner: 'u', version: 2 }), 'STATE');
+  });
+
+  test('[R-12] advance validates monotonic safe time and expires on the exact deadline', () => {
+    const room = createStockroom({ stock: { A: 2 } });
+    room.reserve({ id: 'r', owner: 'u', items: { A: 1 }, ttl: 2 });
+    room.advance(1);
+    const before = room.snapshot();
+    for (const time of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1]) expectCode(() => room.advance(time), 'INVALID_TIME');
+    expectCode(() => room.advance(0), 'INVALID_TIME');
+    expect(room.snapshot()).toEqual(before);
+    expect(room.advance(2)).toEqual({ now: 2, expired: ['r'] });
+    expect(room.get('r')).toMatchObject({ state: 'expired', version: 2 });
+  });
+
+  test('[R-13] expiration ordering uses expiry then JavaScript string order and runs once', () => {
+    const room = createStockroom({ stock: { A: 6 } });
+    room.reserve({ id: 'z', owner: 'u', items: { A: 1 }, ttl: 3 });
+    room.reserve({ id: 'a', owner: 'u', items: { A: 1 }, ttl: 3 });
+    room.reserve({ id: 'early', owner: 'u', items: { A: 1 }, ttl: 2 });
+    room.reserve({ id: 'terminal', owner: 'u', items: { A: 1 }, ttl: 1 });
+    room.confirm({ id: 'terminal', owner: 'u', version: 1 });
+    expect(room.advance(3)).toEqual({ now: 3, expired: ['early', 'a', 'z'] });
+    expect(room.advance(3)).toEqual({ now: 3, expired: [] });
+  });
+
+  test('[R-14] snapshots have the exact shape and sorted reservation history', () => {
+    const room = createStockroom({ stock: { A: 4 } });
+    room.reserve({ id: 'z', owner: 'u', items: { A: 1 }, ttl: 5 });
+    room.reserve({ id: 'a', owner: 'u', items: { A: 1 }, ttl: 5 });
+    room.cancel({ id: 'a', owner: 'u', version: 1 });
+    const snapshot = room.snapshot();
+    expect(Object.keys(snapshot)).toEqual(['schemaVersion', 'now', 'onHand', 'reservations']);
+    expect(snapshot.reservations.map((entry) => entry.id)).toEqual(['a', 'z']);
+    expect(Object.keys(snapshot.reservations[0])).toEqual(['id', 'owner', 'items', 'expiresAt', 'state', 'version', 'initialRequest']);
+    expect(snapshot.reservations[0].initialRequest).toEqual({ owner: 'u', items: { A: 1 }, ttl: 5 });
+  });
+
+  test('[R-15] JSON snapshot restore preserves history and replay while instances evolve independently', () => {
+    const original = createStockroom({ stock: { A: 5 } });
+    original.reserve({ id: 'held', owner: 'u', items: { A: 1 }, ttl: 5 });
+    original.reserve({ id: 'done', owner: 'u', items: { A: 1 }, ttl: 5 });
+    original.confirm({ id: 'done', owner: 'u', version: 1 });
+    const restored = restoreStockroom(JSON.parse(JSON.stringify(original.snapshot())));
+    expect(restored.snapshot()).toEqual(original.snapshot());
+    expect(restored.reserve({ id: 'done', owner: 'u', items: { A: 1 }, ttl: 5 })).toEqual(original.get('done'));
+    restored.cancel({ id: 'held', owner: 'u', version: 1 });
+    expect(restored.get('held').state).toBe('cancelled');
+    expect(original.get('held').state).toBe('held');
+  });
+
+  test('[R-16] caller mutations to inputs, views, availability, and snapshots do not change internal state', () => {
+    const stock = { A: 4 };
+    const items = { A: 1 };
+    const room = createStockroom({ stock });
+    room.reserve({ id: 'r', owner: 'u', items, ttl: 5 });
+    stock.A = 100;
+    items.A = 100;
+    const view = room.get('r');
+    view.items.A = 100;
+    room.availability().A = 100;
+    const snapshot = room.snapshot();
+    snapshot.onHand.A = 100;
+    snapshot.reservations[0].items.A = 100;
+    snapshot.reservations[0].initialRequest.items.A = 100;
+    expect(room.get('r').items).toEqual({ A: 1 });
+    expect(room.availability()).toEqual({ A: 3 });
+    expect(room.snapshot().onHand).toEqual({ A: 4 });
+    expect(room.reserve({ id: 'r', owner: 'u', items: { A: 1 }, ttl: 5 }).items).toEqual({ A: 1 });
+  });
+});
